begin;
set local session_replication_role=replica;
do $$ declare t text; begin foreach t in array array['operations','purchase_dos','stock_movements'] loop execute format('alter sequence %s restart with 8000000000000000000',pg_get_serial_sequence('public.'||t,case when t='stock_movements' then 'posting_order' else 'document_no' end)); end loop; end $$;
create function pg_temp.check_change(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'Uji perubahan gagal: %',label; end if; end $$;
create function pg_temp.reject_change(sql text,expected text) returns void language plpgsql as $$ begin begin execute sql; exception when others then if position(expected in sqlerrm)>0 then return; end if; raise; end; raise exception 'Seharusnya ditolak: %',expected; end $$;
do $$
declare actor uuid; p uuid:=gen_random_uuid(); product uuid:=gen_random_uuid(); account uuid:=gen_random_uuid(); ord uuid:=gen_random_uuid(); receipt uuid:=gen_random_uuid(); sale uuid:=gen_random_uuid();
 supplier_pay uuid:=gen_random_uuid(); customer_pay uuid:=gen_random_uuid(); request uuid; dest uuid; data jsonb; sale_data jsonb; receipt_data jsonb; s jsonb; dt date:='2099-11-05'; delivery uuid:=gen_random_uuid(); line uuid; output_product uuid:=gen_random_uuid(); proc uuid:=gen_random_uuid(); worker uuid:=gen_random_uuid();
begin
 select id into actor from public.profiles where active and role in ('developer','owner') limit 1; perform set_config('request.jwt.claim.sub',actor::text,true);
 insert into public.partners(id,name,is_supplier,is_customer) values(p,'Uji perubahan transaksi',true,true);
 insert into public.products(id,name) values(product,'Ayam perubahan');insert into public.product_units(product_id,unit) values(product,'kg');
 insert into public.cash_accounts(id,name,account_type) values(account,'Kas perubahan','cash');
 perform public.save_operation(gen_random_uuid(),'finance',jsonb_build_object('date',dt,'category','capital','account',account,'amount','1000000','note','Modal uji'),true);
 perform public.create_purchase_do(ord,dt,p,product,null,100,null,'kg',30000,null);
 perform public.confirm_purchase_receipt(receipt,ord,dt,null,100,100,null,null);
 sale_data:=jsonb_build_object('date',dt,'partner',p,'paid','0','discount','0','items',jsonb_build_array(jsonb_build_object('product',product,'unit','kg','quantity','10','price','50000')));
 perform public.save_operation(sale,'sale',sale_data,true);
 perform public.post_payment(supplier_pay,'payable',receipt,dt,account,100000,'Supplier');
 receipt_data:=jsonb_build_object('date',dt,'supplier',p,'product',product,'method','kg','price','20000','actual_weight','100','billing_quantity','100');
 request:=gen_random_uuid();
 perform public.change_transaction(request,'receipt',receipt,'replace',dt,'Harga salah',receipt_data);
 perform public.change_transaction(request,'receipt',receipt,'replace',dt,'Harga salah',receipt_data);
 perform pg_temp.check_change((select bill_amount=2000000 and reversed_by is null from public.purchase_receipts where id=receipt),'harga penerimaan diperbaiki tanpa membatalkan stok terolah');
 perform pg_temp.check_change((select balance::numeric=90 from public.stock_balances where product_id=product),'stok tetap sama pada koreksi harga');
 perform pg_temp.check_change((select balance_amount=1900000 from public.obligations where source_id=receipt),'pembayaran lama tetap sesuai');
 perform pg_temp.check_change((select count(*)=1 from public.transaction_changes where source_id=receipt),'retry perbaikan tidak menggandakan riwayat');
 perform pg_temp.check_change((public.business_summary(dt,dt)->>'cogs')::numeric=200000,'HPP penjualan lama mengikuti koreksi modal');
 supplier_pay:=public.change_transaction(gen_random_uuid(),'payment',supplier_pay,'replace',dt,'Nominal pembayaran salah',jsonb_build_object('date',dt,'account',account,'amount','80000','note','Sesuai bukti'));
 perform pg_temp.check_change((select balance_amount=1920000 from public.obligations where source_id=receipt),'perbaikan pembayaran mengoreksi kas dan hutang bersamaan');
 perform pg_temp.reject_change(format('select public.change_transaction(%L,%L,%L,%L,%L,%L,%L)',gen_random_uuid(),'receipt',receipt,'replace',dt,'Total terlalu kecil',receipt_data||'{"price":"1"}'::jsonb),'lebih kecil');
 perform public.post_payment(customer_pay,'receivable',sale,dt,account,200000,'Cicilan');
 data:=jsonb_set(sale_data,'{items,0,price}','"40000"'); request:=gen_random_uuid();
 perform public.change_transaction(request,'operation',sale,'replace',dt,'Harga jual salah',data);
 perform pg_temp.check_change((select amount=400000 and reversed_by is null from public.operations where id=sale),'koreksi harga jual mempertahankan invoice');
 perform pg_temp.check_change((select balance_amount=200000 from public.obligations where source_id=sale),'cicilan penjualan tidak diposting ulang');
 perform pg_temp.check_change((select count(*)=2 from public.payments where source_id in(sale,receipt) and reversed_by is null),'tidak menggandakan pembayaran aktif');
 perform pg_temp.reject_change(format('select public.reverse_document(%L,%L,%L,%L,%L)',gen_random_uuid(),'operation',sale,dt,'Batal'),'pembayaran aktif');
 perform public.reverse_document(gen_random_uuid(),'payment',customer_pay,dt,'Catatan cicilan salah');
 select id into line from public.operation_items where operation_id=sale;
 perform public.record_delivery(delivery,sale,dt,'sent',jsonb_build_array(jsonb_build_object('item',line,'quantity','10')),null);
 perform pg_temp.reject_change(format('select public.reverse_document(%L,%L,%L,%L,%L)',gen_random_uuid(),'operation',sale,dt,'Batal'),'Pengiriman');
 perform public.cancel_delivery(delivery,'Catatan pengiriman salah');
 request:=gen_random_uuid(); data:=jsonb_set(data,'{items,0,quantity}','"8"');
 dest:=public.change_transaction(request,'operation',sale,'replace',dt,'Jumlah jual salah',data);
 perform pg_temp.check_change(dest<>sale and (select reversed_by=request from public.operations where id=sale),'jumlah berubah membuat pengganti dan mempertahankan asal');
 perform pg_temp.check_change(public.change_transaction(request,'operation',sale,'replace',dt,'Jumlah jual salah',data)=dest,'retry tidak membuat invoice pengganti ganda');
 perform pg_temp.check_change((select balance::numeric=92 from public.stock_balances where product_id=product),'stok pengganti diposting sekali');
 perform public.reverse_document(gen_random_uuid(),'payment',supplier_pay,dt,'Catatan pembayaran salah');
 perform pg_temp.reject_change(format('select public.reverse_document(%L,%L,%L,%L,%L)',gen_random_uuid(),'receipt',receipt,dt,'Batal'),'sudah dipakai');
 perform public.reverse_document(gen_random_uuid(),'operation',dest,dt,'Invoice ganda');
 request:=gen_random_uuid();perform public.reverse_document(request,'receipt',receipt,dt,'Penerimaan ganda');perform public.reverse_document(request,'receipt',receipt,dt,'Penerimaan ganda');
 perform public.rebuild_stock_valuation();s:=public.business_summary(dt,dt);
 perform pg_temp.check_change((select balance::numeric=0 from public.stock_balances where product_id=product),'pembatalan penerimaan mengurangi stok');
 perform pg_temp.check_change(not exists(select 1 from public.obligations where source_id=receipt),'hutang penerimaan batal dihilangkan');
 perform pg_temp.check_change((s->>'net_sales')::numeric=0 and (s->>'net_purchases')::numeric=0 and (s->>'cogs')::numeric=0 and (s->>'profit_complete')::boolean,'omzet pembelian HPP netral setelah batal');
 perform pg_temp.check_change(exists(select 1 from public.sales_purchase_documents where id=receipt and payment_state='cancelled'),'dokumen batal tetap dapat ditelusuri');
 perform pg_temp.reject_change(format('select public.post_payment(%L,%L,%L,%L,%L,1,null)',gen_random_uuid(),'payable',receipt,dt,account),'tidak ditemukan');
 ord:=gen_random_uuid();receipt:=gen_random_uuid();
 perform public.create_purchase_do(ord,dt,p,product,null,20,null,'kg',10000,null);perform public.confirm_purchase_receipt(receipt,ord,dt,null,20,20,null,null);
 insert into public.products(id,name) values(output_product,'Karkas perubahan');insert into public.product_units(product_id,unit) values(output_product,'kg');
 data:=jsonb_build_object('date',dt,'items',jsonb_build_array(jsonb_build_object('product',product,'unit','kg','quantity','10','direction','out'),jsonb_build_object('product',output_product,'unit','kg','quantity','8','direction','in')));
 perform public.save_operation(proc,'production',data,true);data:=jsonb_set(data,'{items,1,quantity}','"6"');
 dest:=public.change_transaction(gen_random_uuid(),'operation',proc,'replace',dt,'Hasil timbang salah',data);
 perform pg_temp.check_change((select balance::numeric=6 from public.stock_balances where product_id=output_product),'perbaikan hasil potong membalik lalu memposting hasil baru');
 perform public.change_transaction(gen_random_uuid(),'operation',dest,'metadata',dt,'Catatan dilengkapi','{"note":"Sesuai timbang ulang"}');
 perform pg_temp.check_change((select note='Sesuai timbang ulang' from public.operations where id=dest),'edit keterangan tanpa mengubah stok');
 insert into auth.users(id,email,email_confirmed_at) values(worker,'transaction-worker-'||worker||'@example.invalid',now());insert into public.profiles(id,full_name,role) values(worker,'Uji produksi','production');
 perform set_config('request.jwt.claim.sub',worker::text,true);
 perform pg_temp.reject_change(format('select public.reverse_document(%L,%L,%L,%L,%L)',gen_random_uuid(),'operation',dest,dt,'Uji akses'),'Tidak memiliki akses');
end $$;
rollback;
